// Command gen-cli-docs generates Markdown reference pages for all
// nwpc_data_client commands into the Sphinx documentation tree
// (default: ./docs/reference/cli). Run from the repository root:
//
//	go run ./tools/gen-cli-docs
//
// The generated files are committed to the repository (Read the Docs build
// jobs have no network access and cannot run Go). CI fails if they are out
// of date; regenerate with `make docs-cli` after changing any cobra command
// definition.
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/cemc-oper/nwpc-data-client/cmd"
	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

func main() {
	outputDir := "./docs/reference/cli"
	if len(os.Args) > 1 {
		outputDir = os.Args[1]
	}

	root := cmd.RootCommand()
	disableAutoGenTag(root)

	if err := os.MkdirAll(outputDir, 0o755); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if err := doc.GenMarkdownTree(root, outputDir); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if err := promoteHeadings(outputDir); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// promoteHeadings rewrites every generated Markdown file so that headings
// start at H1: cobra emits the command title as H2, which triggers the
// MyST "Document headings start at H2, not H1" warning under
// `sphinx-build -W`.
func promoteHeadings(dir string) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".md") {
			continue
		}
		path := filepath.Join(dir, entry.Name())
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		updated := shiftHeadings(string(content))
		if updated != string(content) {
			if err := os.WriteFile(path, []byte(updated), 0o644); err != nil {
				return err
			}
		}
	}
	return nil
}

// shiftHeadings promotes every Markdown heading one level (## -> #).
// Lines inside fenced code blocks are left untouched.
func shiftHeadings(content string) string {
	lines := strings.Split(content, "\n")
	inFence := false
	for i, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "```") {
			inFence = !inFence
			continue
		}
		if !inFence && strings.HasPrefix(line, "##") {
			lines[i] = line[1:]
		}
	}
	return strings.Join(lines, "\n")
}

// disableAutoGenTag drops the "Auto generated by spf13/cobra on <date>"
// footer so regenerated pages stay byte-identical between builds.
func disableAutoGenTag(c *cobra.Command) {
	c.DisableAutoGenTag = true
	for _, sub := range c.Commands() {
		disableAutoGenTag(sub)
	}
}
